        K  := 0.5;
        s33 := 3 * sqrt(33);

        K1 := (2 * (27 + s33))^(1/3) + (2 * (27 - s33))^(1/3);
        K2 := (2 * (1777 + 11 * s33))^(1/3) + (2 * (1777 - 11 * s33))^(1/3);

        C0 := K * sqrt(6 * (K1 -  6)) / 12;
        C1 := K * sqrt(6 * (K1 +  6)) / 12;
        C2 := K * sqrt(6 * (K1 + 18)) / 12;
        C3 := K * sqrt(6 * (K2 + 14)) / 12;

        n1 := (c1 - c0)^2;
        n2 := (c2 - c1)^2;
        n3 := (c2 - c1) * (c1 - c0);

        procedure Add4Axes( ax1, ax2, ax3);
        begin
            Nx[i] := ax1; Ny[i] := ax2; Nz[i] := ax3; Inc(i);
            Nx[i] := ax1; Ny[i] :=-ax2; Nz[i] :=-ax3; Inc(i);
            Nx[i] := ax1; Ny[i] :=-ax3; Nz[i] := ax2; Inc(i);
            Nx[i] := ax1; Ny[i] := ax3; Nz[i] :=-ax2; Inc(i);
        end;
        i := 0;
        Add4Axes( n1, n2, n3);
        Add4Axes(-n1,-n2, n3);
        Add4Axes( n2, n3, n1);
        Add4Axes(-n2,-n3, n1);
        Add4Axes( n3, n1, n2);
        Add4Axes(-n3,-n1, n2);

//        A1 := VectorRotatingAngle( n3,-n2, n1,  n2,-n1, n3,  n1,-n3, n2);
        A1 := ArcCos(((19 + s33)^(1/3) + (19 - s33)^(1/3) - 2) / 6);
        A2 := 2 * A1;
        A3 := 3 * A1;
        A4 := 4 * A1;

        D  := K * 1.00;
    

    

    
        
            
            
            
            
        

        
            
                
                
                
                
                
                
                
                
                
                
                
            

            
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
            
        

        

        
            
            
            
            
            
            
            
            
        
        
        
            
            
            
            
            
            
            
        
        
        
            
            
            
            
            
            
        

        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
    

    
        
        
        
        
        
        
            
            
        

        
        
        
        
        
        
        
        
            
            
        

        
            
            
        

        
            
        

        
            
            
                s33 := 3 * sqrt(33);
                A1 := ArcCos(((19 + s33) ^ (1/3) + (19 - s33) ^ (1/3) - 2) / 6);

                procedure Add2(ax1, ax2);
                begin
                    Edge2[ i, 0] := ax1; Edge2[ i, 1] := ax2; Inc(i);
                    Edge2[ i, 0] := ax2; Edge2[ i, 1] := ax1; Inc(i);
                end;
                i := 0;
                Add2( 0,18);
                Add2( 1,19);
                Add2( 2,17);
                Add2( 3,16);
                Add2( 4,23);
                Add2( 5,22);
                Add2( 6,20);
                Add2( 7,21);
                Add2( 8,15);
                Add2( 9,14);
                Add2(10,12);
                Add2(11,13);

                procedure Add3( ax1, ax2, ax3);
                begin
                    Edge3[ i, 0] := ax1; Edge3[ i, 1] := ax2; Edge3[ i, 2] := ax3; Inc(i);
                    Edge3[ i, 0] := ax2; Edge3[ i, 1] := ax3; Edge3[ i, 2] := ax1; Inc(i);
                    Edge3[ i, 0] := ax3; Edge3[ i, 1] := ax1; Edge3[ i, 2] := ax2; Inc(i);
                end;
                i := 0;
                Add3( 0, 8,16);
                Add3( 1, 9,17);
                Add3( 2,10,18);
                Add3( 3,11,19);
                Add3( 4,12,20);
                Add3( 5,13,21);
                Add3( 6,14,22);
